const e="2048",n="status: complete\n\nnotes: Every capability in the spec is built. It's plain HTML/CSS/JS with no\nbuild step and no dependencies — open `index.html` and play, or `node serve.js`\nif you'd rather have a URL. All the rules live in `engine.js` with no DOM\nreference, which is what let me test them properly: `node test.js` runs 27\nchecks covering the 90/10 spawn split (with a distribution check over 4000\ndraws), one-merge-per-tile (`4,4,8` → `8,8`, `2,2,2` → `4,2`), rejection of\nno-op moves and the absence of a spawn on them, scoring, best-score and\ngame-state persistence, win-at-2048 with play continuing after, game-over\ndetection including the case where the final spawn locks the board, multi-level\nundo, and a 200-game random fuzz asserting board invariants after every move.\nAll 27 pass. The animation is done by keeping a stable tile id across a move\nso each tile owns one DOM element that gets retargeted rather than redrawn —\ntiles slide via a CSS transform transition, merges resolve 110ms later, and\nspawned tiles delay their pop by the same 110ms so they land after the slide.\nThe one thing I could not do is look at it: no browser automation was available\nin this environment (the screenshot tooling was not permitted), so I wrote\n`smoke.js` instead, which executes `app.js` for real against a small DOM\nstand-in built from the ids in `index.html` and drives boot, arrow keys,\nswipes, undo, new game, the win overlay and the game-over overlay — 13 checks,\nall passing, including one that asserts the slide duration in `app.js` still\nmatches `--slide` in `styles.css`. That proves the wiring, not the pixels; the\nvisual layout and the easing are reasoned about and geometrically checked (the\ntranslate math is exact at any board width) but not eyeballed. If you want one\nthing verified by eye first, make it the merge animation.\n",t=JSON.parse(`[{"path":"app.js","bytes":7530,"text":"/*\\n * 2048 — browser shell: rendering, animation, input.\\n * All rules live in engine.js; this file only reflects state onto the DOM.\\n */\\n(function () {\\n  'use strict';\\n\\n  var SLIDE_MS = 110; // must match --slide in styles.css\\n\\n  var el = {\\n    board: document.getElementById('board'),\\n    tiles: document.getElementById('tiles'),\\n    score: document.getElementById('score'),\\n    best: document.getElementById('best'),\\n    undo: document.getElementById('undo'),\\n    newGame: document.getElementById('new'),\\n    overlay: document.getElementById('overlay'),\\n    overlayMessage: document.getElementById('overlay-message'),\\n    keepGoing: document.getElementById('keep-going'),\\n    retry: document.getElementById('retry'),\\n    status: document.getElementById('status')\\n  };\\n\\n  var game = new Game2048();\\n  var tileEls = new Map(); // tile id -> .tile element\\n  var pending = null;      // merge commits waiting for the slide to finish\\n\\n  /* -------------------------------------------------------------- render */\\n\\n  function createTile(tile, extraClass) {\\n    var node = document.createElement('div');\\n    node.className = 'tile' + (extraClass ? ' ' + extraClass : '');\\n    node.style.setProperty('--r', tile.r);\\n    node.style.setProperty('--c', tile.c);\\n    var inner = document.createElement('div');\\n    inner.className = 'tile-inner';\\n    node.appendChild(inner);\\n    setValue(node, tile.value);\\n    el.tiles.appendChild(node);\\n    return node;\\n  }\\n\\n  function setValue(node, value) {\\n    node.dataset.value = value > 2048 ? 'super' : String(value);\\n    node.firstChild.textContent = value;\\n  }\\n\\n  function moveTo(node, r, c) {\\n    node.style.setProperty('--r', r);\\n    node.style.setProperty('--c', c);\\n  }\\n\\n  /* Wipe and rebuild — used on load, new game and undo. */\\n  function fullRender() {\\n    flushPending();\\n    el.tiles.textContent = '';\\n    tileEls = new Map();\\n    game.tiles().forEach(function (t) { tileEls.set(t.id, createTile(t)); });\\n    syncChrome();\\n  }\\n\\n  /* Animate one move: everything slides, then merges land. */\\n  function renderMove(res) {\\n    flushPending();\\n\\n    var next = new Map();\\n    var kept = new Set();\\n    var commits = [];\\n\\n    res.tiles.forEach(function (rec) {\\n      if (rec.spawned) {\\n        var fresh = createTile(rec, 'tile-new');\\n        next.set(rec.id, fresh);\\n        kept.add(fresh);\\n        return;\\n      }\\n\\n      var primary = tileEls.get(rec.sources[0].id) || createTile(rec.sources[0]);\\n      moveTo(primary, rec.r, rec.c);\\n      primary.classList.remove('tile-new', 'tile-merged', 'tile-absorbed');\\n      next.set(rec.id, primary);\\n      kept.add(primary);\\n\\n      if (rec.merged) {\\n        var absorbed = tileEls.get(rec.sources[1].id) || createTile(rec.sources[1]);\\n        absorbed.classList.add('tile-absorbed');\\n        moveTo(absorbed, rec.r, rec.c);\\n        kept.add(absorbed);\\n        commits.push(function () {\\n          absorbed.remove();\\n          setValue(primary, rec.value);\\n          primary.classList.add('tile-merged');\\n        });\\n      }\\n    });\\n\\n    tileEls.forEach(function (node) { if (!kept.has(node)) node.remove(); });\\n    tileEls = next;\\n\\n    if (commits.length) {\\n      pending = { commits: commits, timer: setTimeout(runPending, SLIDE_MS) };\\n    }\\n\\n    if (res.gained) showGain(res.gained);\\n    syncChrome();\\n  }\\n\\n  function runPending() {\\n    if (!pending) return;\\n    var commits = pending.commits;\\n    clearTimeout(pending.timer);\\n    pending = null;\\n    commits.forEach(function (fn) { fn(); });\\n  }\\n\\n  /* If a second move arrives mid-animation, land the previous one first. */\\n  function flushPending() { runPending(); }\\n\\n  function showGain(amount) {\\n    var node = document.createElement('div');\\n    node.className = 'gain';\\n    node.textContent = '+' + amount;\\n    el.score.parentNode.appendChild(node);\\n    setTimeout(function () { node.remove(); }, 700);\\n  }\\n\\n  /* --------------------------------------------------------- score, state */\\n\\n  function syncChrome() {\\n    el.score.textContent = game.score;\\n    el.best.textContent = game.best;\\n    el.undo.disabled = !game.canUndo();\\n    renderOverlay();\\n  }\\n\\n  function renderOverlay() {\\n    if (game.over) {\\n      el.overlay.hidden = false;\\n      el.overlay.classList.remove('win');\\n      el.overlayMessage.textContent = 'Game over!';\\n      el.keepGoing.hidden = true;\\n      el.retry.textContent = 'Try again';\\n      announce('Game over. Final score ' + game.score + '.');\\n    } else if (game.won && !game.keepGoing) {\\n      el.overlay.hidden = false;\\n      el.overlay.classList.add('win');\\n      el.overlayMessage.textContent = 'You win!';\\n      el.keepGoing.hidden = false;\\n      el.retry.textContent = 'New game';\\n      announce('You reached 2048. Score ' + game.score + '.');\\n    } else {\\n      el.overlay.hidden = true;\\n      el.overlay.classList.remove('win');\\n    }\\n  }\\n\\n  function announce(text) {\\n    if (el.status.textContent !== text) el.status.textContent = text;\\n  }\\n\\n  function blocked() {\\n    return game.over || (game.won && !game.keepGoing);\\n  }\\n\\n  /* --------------------------------------------------------------- input */\\n\\n  var KEYS = {\\n    ArrowUp: 'up', ArrowDown: 'down', ArrowLeft: 'left', ArrowRight: 'right',\\n    Up: 'up', Down: 'down', Left: 'left', Right: 'right',\\n    w: 'up', a: 'left', s: 'down', d: 'right',\\n    W: 'up', A: 'left', S: 'down', D: 'right',\\n    k: 'up', h: 'left', j: 'down', l: 'right'\\n  };\\n\\n  function play(dir) {\\n    if (blocked()) return;\\n    var res = game.move(dir);\\n    if (!res) return; // a move that changes nothing is rejected\\n    renderMove(res);\\n  }\\n\\n  document.addEventListener('keydown', function (event) {\\n    if (event.altKey || event.ctrlKey || event.metaKey) return;\\n    var dir = KEYS[event.key];\\n    if (dir) {\\n      event.preventDefault();\\n      play(dir);\\n      return;\\n    }\\n    if (event.key === 'u' || event.key === 'U') { event.preventDefault(); doUndo(); }\\n    if (event.key === 'n' || event.key === 'N') { event.preventDefault(); doNewGame(); }\\n  });\\n\\n  // Swipe. Pointer events cover touch, pen and mouse drags.\\n  var swipe = null;\\n  var SWIPE_MIN = 24;\\n\\n  el.board.addEventListener('pointerdown', function (event) {\\n    if (event.button !== undefined && event.button !== 0) return;\\n    swipe = { x: event.clientX, y: event.clientY };\\n  });\\n\\n  el.board.addEventListener('pointerup', function (event) {\\n    if (!swipe) return;\\n    var dx = event.clientX - swipe.x;\\n    var dy = event.clientY - swipe.y;\\n    swipe = null;\\n    if (Math.max(Math.abs(dx), Math.abs(dy)) < SWIPE_MIN) return;\\n    if (Math.abs(dx) > Math.abs(dy)) play(dx > 0 ? 'right' : 'left');\\n    else play(dy > 0 ? 'down' : 'up');\\n  });\\n\\n  el.board.addEventListener('pointercancel', function () { swipe = null; });\\n  el.board.addEventListener('touchmove', function (e) { e.preventDefault(); }, { passive: false });\\n\\n  /* ------------------------------------------------------------- actions */\\n\\n  function doNewGame() {\\n    game.newGame();\\n    fullRender();\\n    el.board.focus({ preventScroll: true });\\n  }\\n\\n  function doUndo() {\\n    if (!game.undo()) return;\\n    fullRender();\\n  }\\n\\n  el.newGame.addEventListener('click', doNewGame);\\n  el.retry.addEventListener('click', doNewGame);\\n  el.undo.addEventListener('click', doUndo);\\n\\n  el.keepGoing.addEventListener('click', function () {\\n    game.keepGoing = true;\\n    game.save();\\n    renderOverlay();\\n    el.board.focus({ preventScroll: true });\\n  });\\n\\n  /* ---------------------------------------------------------------- boot */\\n\\n  fullRender();\\n  el.board.focus({ preventScroll: true });\\n})();\\n"},{"path":"engine.js","bytes":10395,"text":"/*\\n * 2048 — game engine.\\n *\\n * Pure logic: no DOM. Runs in the browser (attaches to window) and in Node\\n * (module.exports) so the same code is exercised by test.js.\\n *\\n * A tile is { id, value, r, c }. Ids are stable across a move for every tile\\n * that survives it, which is what lets the renderer animate instead of redraw.\\n */\\n(function (root, factory) {\\n  var api = factory();\\n  if (typeof module === 'object' && module.exports) {\\n    module.exports = api;\\n  } else {\\n    root.Game2048 = api.Game2048;\\n    root.DIRECTIONS = api.DIRECTIONS;\\n  }\\n})(typeof self !== 'undefined' ? self : this, function () {\\n  'use strict';\\n\\n  var SIZE = 4;\\n  var WIN_VALUE = 2048;\\n  var DIRECTIONS = ['up', 'down', 'left', 'right'];\\n  var STATE_KEY = 'game2048.state';\\n  var BEST_KEY = 'game2048.best';\\n\\n  function Game2048(opts) {\\n    opts = opts || {};\\n    this.size = opts.size || SIZE;\\n    this.winValue = opts.winValue || WIN_VALUE;\\n    this.rng = opts.rng || Math.random;\\n    this.storage = opts.storage !== undefined ? opts.storage : defaultStorage();\\n    this.maxUndo = opts.maxUndo === undefined ? 16 : opts.maxUndo;\\n\\n    this.best = this.readBest();\\n    if (!this.restore()) this.newGame();\\n  }\\n\\n  function defaultStorage() {\\n    try {\\n      if (typeof localStorage === 'undefined') return null;\\n      var probe = '__2048probe__';\\n      localStorage.setItem(probe, '1');\\n      localStorage.removeItem(probe);\\n      return localStorage;\\n    } catch (e) {\\n      return null; // private mode / blocked storage — play on, just don't persist\\n    }\\n  }\\n\\n  /* ---------------------------------------------------------------- state */\\n\\n  Game2048.prototype.newGame = function () {\\n    this.cells = new Array(this.size * this.size).fill(null);\\n    this.score = 0;\\n    this.won = false;\\n    this.keepGoing = false;\\n    this.over = false;\\n    this.history = [];\\n    this.nextId = 1;\\n    this.spawn();\\n    this.spawn();\\n    this.save();\\n  };\\n\\n  Game2048.prototype.index = function (r, c) { return r * this.size + c; };\\n  Game2048.prototype.at = function (r, c) { return this.cells[this.index(r, c)]; };\\n\\n  Game2048.prototype.tiles = function () {\\n    return this.cells.filter(Boolean);\\n  };\\n\\n  Game2048.prototype.emptyIndices = function () {\\n    var out = [];\\n    for (var i = 0; i < this.cells.length; i++) if (!this.cells[i]) out.push(i);\\n    return out;\\n  };\\n\\n  /* 90% a 2, 10% a 4, in a random empty cell. */\\n  Game2048.prototype.spawn = function () {\\n    var empty = this.emptyIndices();\\n    if (!empty.length) return null;\\n    var idx = empty[Math.floor(this.rng() * empty.length) % empty.length];\\n    var tile = {\\n      id: this.nextId++,\\n      value: this.rng() < 0.9 ? 2 : 4,\\n      r: Math.floor(idx / this.size),\\n      c: idx % this.size\\n    };\\n    this.cells[idx] = tile;\\n    return tile;\\n  };\\n\\n  /* Cell coordinates of each row/column, ordered destination-first for \`dir\`. */\\n  Game2048.prototype.lines = function (dir) {\\n    var n = this.size, out = [];\\n    for (var i = 0; i < n; i++) {\\n      var line = [];\\n      for (var j = 0; j < n; j++) {\\n        if (dir === 'left') line.push([i, j]);\\n        else if (dir === 'right') line.push([i, n - 1 - j]);\\n        else if (dir === 'up') line.push([j, i]);\\n        else line.push([n - 1 - j, i]);\\n      }\\n      out.push(line);\\n    }\\n    return out;\\n  };\\n\\n  /* ----------------------------------------------------------------- move */\\n\\n  /*\\n   * Returns null when the move changes nothing (and nothing spawns), otherwise\\n   * a record of what happened, shaped for the renderer:\\n   *   { moved, gained, justWon, over, tiles: [ ... ] }\\n   * Each entry in \`tiles\` is either a surviving tile with its \`sources\`\\n   * (one entry, or two when it is a merge) or the freshly spawned tile.\\n   */\\n  Game2048.prototype.move = function (dir) {\\n    if (this.over) return null;\\n    if (DIRECTIONS.indexOf(dir) === -1) return null;\\n\\n    var snapshot = this.snapshot();\\n    var newCells = new Array(this.size * this.size).fill(null);\\n    var records = [];\\n    var gained = 0;\\n    var moved = false;\\n    var lines = this.lines(dir);\\n\\n    for (var l = 0; l < lines.length; l++) {\\n      var line = lines[l];\\n      var lineTiles = [];\\n      for (var j = 0; j < line.length; j++) {\\n        var t = this.at(line[j][0], line[j][1]);\\n        if (t) lineTiles.push(t);\\n      }\\n\\n      // Walk the compacted line; a tile may take part in at most one merge,\\n      // so 4,4,8 -> 8,8 rather than 16.\\n      var slots = [];\\n      var i = 0;\\n      while (i < lineTiles.length) {\\n        if (i + 1 < lineTiles.length && lineTiles[i].value === lineTiles[i + 1].value) {\\n          slots.push({ value: lineTiles[i].value * 2, sources: [lineTiles[i], lineTiles[i + 1]] });\\n          gained += lineTiles[i].value * 2;\\n          i += 2;\\n        } else {\\n          slots.push({ value: lineTiles[i].value, sources: [lineTiles[i]] });\\n          i += 1;\\n        }\\n      }\\n\\n      for (var k = 0; k < slots.length; k++) {\\n        var slot = slots[k];\\n        var r = line[k][0], c = line[k][1];\\n        var primary = slot.sources[0];\\n        var isMerge = slot.sources.length > 1;\\n        if (isMerge || primary.r !== r || primary.c !== c) moved = true;\\n\\n        newCells[this.index(r, c)] = { id: primary.id, value: slot.value, r: r, c: c };\\n        records.push({\\n          id: primary.id,\\n          value: slot.value,\\n          r: r,\\n          c: c,\\n          merged: isMerge,\\n          spawned: false,\\n          sources: slot.sources.map(function (s) {\\n            return { id: s.id, value: s.value, r: s.r, c: s.c };\\n          })\\n        });\\n      }\\n    }\\n\\n    if (!moved) return null; // no-op move: rejected, nothing spawns\\n\\n    this.cells = newCells;\\n    this.score += gained;\\n    if (this.score > this.best) { this.best = this.score; this.writeBest(); }\\n\\n    this.history.push(snapshot);\\n    while (this.history.length > this.maxUndo) this.history.shift();\\n\\n    var justWon = false;\\n    if (!this.won) {\\n      for (var m = 0; m < records.length; m++) {\\n        if (records[m].value >= this.winValue) { this.won = true; justWon = true; break; }\\n      }\\n    }\\n\\n    var spawned = this.spawn();\\n    if (spawned) {\\n      records.push({\\n        id: spawned.id, value: spawned.value, r: spawned.r, c: spawned.c,\\n        merged: false, spawned: true, sources: []\\n      });\\n    }\\n\\n    this.over = !this.canMove();\\n    this.save();\\n\\n    return { moved: true, gained: gained, justWon: justWon, over: this.over, tiles: records };\\n  };\\n\\n  /* Game over: grid full and no equal neighbours. */\\n  Game2048.prototype.canMove = function () {\\n    if (this.emptyIndices().length) return true;\\n    for (var r = 0; r < this.size; r++) {\\n      for (var c = 0; c < this.size; c++) {\\n        var v = this.at(r, c).value;\\n        if (c + 1 < this.size && this.at(r, c + 1).value === v) return true;\\n        if (r + 1 < this.size && this.at(r + 1, c).value === v) return true;\\n      }\\n    }\\n    return false;\\n  };\\n\\n  Game2048.prototype.highest = function () {\\n    return this.cells.reduce(function (max, t) { return t && t.value > max ? t.value : max; }, 0);\\n  };\\n\\n  /* ----------------------------------------------------------------- undo */\\n\\n  Game2048.prototype.canUndo = function () { return this.history.length > 0; };\\n\\n  Game2048.prototype.undo = function () {\\n    if (!this.history.length) return false;\\n    this.applySnapshot(this.history.pop());\\n    this.save();\\n    return true;\\n  };\\n\\n  Game2048.prototype.snapshot = function () {\\n    return {\\n      cells: this.cells.map(function (t) {\\n        return t ? { id: t.id, value: t.value } : null;\\n      }),\\n      score: this.score,\\n      won: this.won,\\n      keepGoing: this.keepGoing,\\n      over: this.over,\\n      nextId: this.nextId\\n    };\\n  };\\n\\n  Game2048.prototype.applySnapshot = function (s) {\\n    var self = this;\\n    this.cells = s.cells.map(function (t, i) {\\n      return t ? { id: t.id, value: t.value, r: Math.floor(i / self.size), c: i % self.size } : null;\\n    });\\n    this.score = s.score;\\n    this.won = s.won;\\n    this.keepGoing = s.keepGoing;\\n    this.over = s.over;\\n    this.nextId = s.nextId;\\n  };\\n\\n  /* ---------------------------------------------------------- persistence */\\n\\n  Game2048.prototype.readBest = function () {\\n    if (!this.storage) return 0;\\n    var raw = this.storage.getItem(BEST_KEY);\\n    var n = raw === null ? 0 : parseInt(raw, 10);\\n    return isNaN(n) ? 0 : n;\\n  };\\n\\n  Game2048.prototype.writeBest = function () {\\n    if (!this.storage) return;\\n    try { this.storage.setItem(BEST_KEY, String(this.best)); } catch (e) { /* quota */ }\\n  };\\n\\n  Game2048.prototype.save = function () {\\n    if (!this.storage) return;\\n    var payload = this.snapshot();\\n    payload.history = this.history;\\n    payload.size = this.size;\\n    try { this.storage.setItem(STATE_KEY, JSON.stringify(payload)); } catch (e) { /* quota */ }\\n  };\\n\\n  Game2048.prototype.restore = function () {\\n    if (!this.storage) return false;\\n    var raw = this.storage.getItem(STATE_KEY);\\n    if (!raw) return false;\\n    try {\\n      var s = JSON.parse(raw);\\n      if (!s || !Array.isArray(s.cells) || s.cells.length !== this.size * this.size) return false;\\n      this.applySnapshot(s);\\n      this.history = Array.isArray(s.history) ? s.history : [];\\n      this.over = !this.canMove();\\n      return true;\\n    } catch (e) {\\n      return false;\\n    }\\n  };\\n\\n  Game2048.prototype.clearSaved = function () {\\n    if (!this.storage) return;\\n    try { this.storage.removeItem(STATE_KEY); } catch (e) { /* ignore */ }\\n  };\\n\\n  /* --------------------------------------------------------------- testing */\\n\\n  /* Load a grid of plain numbers (0/null = empty). Used by the tests. */\\n  Game2048.prototype.setGrid = function (rows) {\\n    this.cells = new Array(this.size * this.size).fill(null);\\n    this.nextId = 1;\\n    for (var r = 0; r < this.size; r++) {\\n      for (var c = 0; c < this.size; c++) {\\n        var v = rows[r][c];\\n        if (v) this.cells[this.index(r, c)] = { id: this.nextId++, value: v, r: r, c: c };\\n      }\\n    }\\n    this.over = !this.canMove();\\n    this.history = [];\\n  };\\n\\n  Game2048.prototype.getGrid = function () {\\n    var rows = [];\\n    for (var r = 0; r < this.size; r++) {\\n      var row = [];\\n      for (var c = 0; c < this.size; c++) {\\n        var t = this.at(r, c);\\n        row.push(t ? t.value : 0);\\n      }\\n      rows.push(row);\\n    }\\n    return rows;\\n  };\\n\\n  return { Game2048: Game2048, DIRECTIONS: DIRECTIONS, WIN_VALUE: WIN_VALUE };\\n});\\n"},{"path":"index.html","bytes":2538,"text":"<!DOCTYPE html>\\n<html lang=\\"en\\">\\n<head>\\n<meta charset=\\"utf-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no\\">\\n<meta name=\\"theme-color\\" content=\\"#faf8ef\\">\\n<title>2048</title>\\n<link rel=\\"stylesheet\\" href=\\"styles.css\\">\\n<link rel=\\"icon\\" href=\\"data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'><rect width='32' height='32' rx='6' fill='%23edc22e'/></svg>\\">\\n</head>\\n<body>\\n<main class=\\"app\\">\\n\\n  <header>\\n    <h1>2048</h1>\\n    <div class=\\"scores\\">\\n      <div class=\\"score\\">\\n        <span class=\\"label\\">Score</span>\\n        <span class=\\"value\\" id=\\"score\\" aria-live=\\"polite\\">0</span>\\n      </div>\\n      <div class=\\"score\\">\\n        <span class=\\"label\\">Best</span>\\n        <span class=\\"value\\" id=\\"best\\">0</span>\\n      </div>\\n    </div>\\n  </header>\\n\\n  <div class=\\"toolbar\\">\\n    <p class=\\"hint\\">Join the tiles, get to <strong>2048</strong>.</p>\\n    <div class=\\"actions\\">\\n      <button type=\\"button\\" id=\\"undo\\" title=\\"Undo the last move (U)\\">Undo</button>\\n      <button type=\\"button\\" id=\\"new\\">New game</button>\\n    </div>\\n  </div>\\n\\n  <div class=\\"board\\" id=\\"board\\" tabindex=\\"0\\" role=\\"application\\"\\n       aria-label=\\"2048 board. Use the arrow keys to move tiles.\\">\\n    <div class=\\"grid\\" aria-hidden=\\"true\\">\\n      <div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div>\\n      <div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div>\\n      <div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div>\\n      <div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div><div class=\\"cell\\"></div>\\n    </div>\\n\\n    <div class=\\"tiles\\" id=\\"tiles\\"></div>\\n\\n    <div class=\\"overlay\\" id=\\"overlay\\" hidden>\\n      <p id=\\"overlay-message\\"></p>\\n      <div class=\\"buttons\\">\\n        <button type=\\"button\\" id=\\"keep-going\\" hidden>Keep going</button>\\n        <button type=\\"button\\" id=\\"retry\\">Try again</button>\\n      </div>\\n    </div>\\n  </div>\\n\\n  <p class=\\"sr-only\\" id=\\"status\\" aria-live=\\"polite\\" style=\\"position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);\\"></p>\\n\\n  <footer>\\n    <strong>How to play:</strong> use the <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> keys\\n    (or swipe) to slide the tiles. Tiles with the same number merge into one when they touch.\\n    <kbd>U</kbd> undoes a move, <kbd>N</kbd> starts a new game.\\n  </footer>\\n\\n</main>\\n\\n<script src=\\"engine.js\\"><\/script>\\n<script src=\\"app.js\\"><\/script>\\n</body>\\n</html>\\n"},{"path":"package.json","bytes":338,"text":"{\\n  \\"name\\": \\"2048\\",\\n  \\"version\\": \\"1.0.0\\",\\n  \\"private\\": true,\\n  \\"description\\": \\"Sliding tile puzzle: merge equal tiles on a 4x4 grid until 2048 appears.\\",\\n  \\"type\\": \\"commonjs\\",\\n  \\"scripts\\": {\\n    \\"test\\": \\"node test.js && node smoke.js\\",\\n    \\"test:engine\\": \\"node test.js\\",\\n    \\"test:ui\\": \\"node smoke.js\\",\\n    \\"start\\": \\"node serve.js\\"\\n  }\\n}\\n"},{"path":"README.md","bytes":3733,"text":"# 2048\\n\\nSliding tile puzzle: merge equal tiles on a 4×4 grid until 2048 appears.\\n\\nPlain HTML, CSS and JavaScript. No build step, no dependencies, no framework.\\n\\n## Run it\\n\\nOpen \`index.html\` in a browser. That's it.\\n\\nIf you'd rather serve it over HTTP (Node 18+, no install needed):\\n\\n\`\`\`\\nnode serve.js          # http://localhost:8080/\\nnode serve.js 3000     # or pick a port\\n\`\`\`\\n\\n## Play\\n\\n| Input | Does |\\n| --- | --- |\\n| <kbd>←</kbd> <kbd>↑</kbd> <kbd>→</kbd> <kbd>↓</kbd> | Slide the tiles. \`WASD\` and \`hjkl\` work too. |\\n| Swipe | Same, on touch screens (and mouse drags on the board). |\\n| <kbd>U</kbd> / **Undo** | Take back a move — up to 16 levels deep. |\\n| <kbd>N</kbd> / **New game** | Start over. |\\n\\nScore and best score sit top right; the best score and the game in progress\\nare both kept in \`localStorage\`, so closing the tab and coming back resumes\\nwhere you left off. Reaching 2048 raises a **You win!** overlay with\\n**Keep going** (play on for a higher tile) and **New game**. Running out of\\nmoves raises **Game over!** with **Try again**.\\n\\n## Tests\\n\\n\`\`\`\\nnode test.js     # game rules\\nnode smoke.js    # UI wiring\\n\`\`\`\\n\\nor \`npm test\` to run both. Nothing to install first.\\n\\n\`test.js\` covers the rules directly against the engine: the 90/10 spawn split\\n(including a distribution check over 4000 draws), one-merge-per-tile\\n(\`4,4,8\` → \`8,8\`), rejection of no-op moves, scoring, win and game-over\\ndetection, undo, persistence, and a 200-game random fuzz that asserts the\\nboard invariants after every move.\\n\\n\`smoke.js\` runs \`app.js\` for real against a small DOM stand-in built from the\\nids in \`index.html\`, and drives it through boot, arrow keys, swipes, undo,\\nnew game, the win overlay and the game-over overlay. It cannot tell you the\\npage *looks* right — but it catches broken wiring, and it checks that the\\nslide duration in \`app.js\` still matches \`--slide\` in \`styles.css\`.\\n\\n## Layout\\n\\n| File | |\\n| --- | --- |\\n| \`engine.js\` | All the rules. No DOM — runs in the browser and in Node. |\\n| \`app.js\` | Rendering, animation, keyboard and swipe input. |\\n| \`styles.css\` | Board, tile palette, animations. |\\n| \`index.html\` | Markup. |\\n| \`serve.js\` | Optional static server. |\\n| \`test.js\`, \`smoke.js\` | Tests. |\\n\\n## How the animation works\\n\\nThe engine hands out a stable \`id\` per tile and keeps it across a move, so\\n\`app.js\` can hold one DOM element per tile and just retarget it instead of\\nredrawing the board.\\n\\nEach move returns a record per surviving tile listing its \`sources\` — one\\nentry normally, two when it's a merge. The renderer moves every source element\\nto the destination cell (CSS transitions the \`transform\`, so tiles slide),\\nthen 110 ms later removes the absorbed half of each merge, doubles the\\nsurvivor's value and pops it. Newly spawned tiles are placed immediately but\\ntheir appear-animation is delayed by the same 110 ms, so they arrive after\\nthe slide has settled rather than during it.\\n\\nIf a second move arrives mid-slide, the pending merges are committed early so\\nthe board is never left in a half-resolved state.\\n\\nPosition comes from \`translate(calc(var(--c) * (100% + var(--gap))), …)\` on\\neach tile — percentages inside \`translate()\` resolve against the tile's own\\nsize, so the board stays correct at any width without measuring anything in\\nJavaScript.\\n\\n## Notes\\n\\n- The board is square and fluid up to 480px wide; it works down to narrow\\n  phone widths.\\n- \`prefers-reduced-motion: reduce\` collapses every animation to ~0ms.\\n- Storage is wrapped in a try/catch — with cookies or storage blocked the game\\n  still plays, it just won't remember anything.\\n- Undo is capped at 16 levels so the saved state stays small.\\n- Undo does not lower the best score: best is a high-water mark.\\n"},{"path":"serve.js","bytes":1242,"text":"/*\\n * Optional static server, for when you'd rather not open the file directly:\\n *   node serve.js [port]\\n */\\n'use strict';\\n\\nvar http = require('http');\\nvar fs = require('fs');\\nvar path = require('path');\\n\\nvar root = __dirname;\\nvar port = parseInt(process.argv[2], 10) || 8080;\\n\\nvar TYPES = {\\n  '.html': 'text/html; charset=utf-8',\\n  '.css': 'text/css; charset=utf-8',\\n  '.js': 'text/javascript; charset=utf-8',\\n  '.json': 'application/json; charset=utf-8',\\n  '.svg': 'image/svg+xml',\\n  '.md': 'text/markdown; charset=utf-8'\\n};\\n\\nhttp.createServer(function (req, res) {\\n  var rel = decodeURIComponent(req.url.split('?')[0]);\\n  if (rel === '/') rel = '/index.html';\\n\\n  var file = path.join(root, path.normalize(rel));\\n  if (file.indexOf(root) !== 0) {\\n    res.writeHead(403).end('Forbidden');\\n    return;\\n  }\\n\\n  fs.readFile(file, function (err, body) {\\n    if (err) {\\n      res.writeHead(404, { 'Content-Type': 'text/plain' }).end('Not found');\\n      return;\\n    }\\n    res.writeHead(200, {\\n      'Content-Type': TYPES[path.extname(file).toLowerCase()] || 'application/octet-stream',\\n      'Cache-Control': 'no-cache'\\n    });\\n    res.end(body);\\n  });\\n}).listen(port, function () {\\n  console.log('2048 is at http://localhost:' + port + '/');\\n});\\n"},{"path":"smoke.js","bytes":11639,"text":"/*\\n * UI smoke test:  node smoke.js\\n *\\n * There is no browser here, so this runs app.js against a small DOM stand-in\\n * whose element ids are read out of index.html. It won't tell you the game\\n * *looks* right, but it does prove the markup, the script wiring and the\\n * keyboard/undo/overlay paths hold together.\\n */\\n'use strict';\\n\\nvar fs = require('fs');\\nvar vm = require('vm');\\nvar path = require('path');\\n\\nvar here = __dirname;\\nvar passed = 0, failed = 0;\\n\\nfunction check(name, fn) {\\n  try { fn(); passed++; console.log('  ok   ' + name); }\\n  catch (e) { failed++; console.log('  FAIL ' + name + '\\\\n       ' + e.message); }\\n}\\nfunction ok(cond, what) { if (!cond) throw new Error(what || 'expected truthy'); }\\nfunction eq(a, b, what) {\\n  if (String(a) !== String(b)) throw new Error((what || 'value') + ': expected ' + b + ', got ' + a);\\n}\\n\\n/* ------------------------------------------------------------- tiny DOM */\\n\\nfunction Element(tag) {\\n  this.tagName = tag;\\n  this.className = '';\\n  this.children = [];\\n  this.text = '';\\n  this.dataset = {};\\n  this.styles = {};\\n  this.listeners = {};\\n  this.parentNode = null;\\n  this.hidden = false;\\n  this.disabled = false;\\n  this.style = { setProperty: function (k, v) { this.styles[k] = String(v); }.bind(this) };\\n  var self = this;\\n  this.classList = {\\n    add: function () { [].forEach.call(arguments, function (c) { if (!self.has(c)) self.className += ' ' + c; }); },\\n    remove: function () { [].forEach.call(arguments, function (c) {\\n      self.className = self.className.split(/\\\\s+/).filter(function (x) { return x && x !== c; }).join(' ');\\n    }); },\\n    contains: function (c) { return self.has(c); }\\n  };\\n}\\nElement.prototype.has = function (c) { return this.className.split(/\\\\s+/).indexOf(c) !== -1; };\\nElement.prototype.appendChild = function (child) { child.parentNode = this; this.children.push(child); return child; };\\nElement.prototype.remove = function () {\\n  if (!this.parentNode) return;\\n  var i = this.parentNode.children.indexOf(this);\\n  if (i >= 0) this.parentNode.children.splice(i, 1);\\n  this.parentNode = null;\\n};\\nElement.prototype.addEventListener = function (type, fn) {\\n  (this.listeners[type] = this.listeners[type] || []).push(fn);\\n};\\nElement.prototype.dispatch = function (type, event) {\\n  (this.listeners[type] || []).forEach(function (fn) { fn(event); });\\n};\\nElement.prototype.focus = function () {};\\nObject.defineProperty(Element.prototype, 'firstChild', {\\n  get: function () { return this.children[0] || null; }\\n});\\nObject.defineProperty(Element.prototype, 'textContent', {\\n  get: function () {\\n    return this.text + this.children.map(function (c) { return c.textContent; }).join('');\\n  },\\n  set: function (v) { this.children = []; this.text = String(v); }\\n});\\n\\nvar html = fs.readFileSync(path.join(here, 'index.html'), 'utf8');\\nvar ids = {};\\nvar idNames = [];\\nhtml.replace(/id=\\"([^\\"]+)\\"/g, function (_, id) { idNames.push(id); return _; });\\n\\n/* Fresh stand-ins for every id in the page, each hung off a common parent so\\n   code that walks up to parentNode has something to find. */\\nfunction resetIds() {\\n  var body = new Element('body');\\n  idNames.forEach(function (id) { ids[id] = body.appendChild(new Element('div')); });\\n}\\nresetIds();\\n\\nvar document = {\\n  listeners: {},\\n  getElementById: function (id) { return ids[id] || null; },\\n  createElement: function (tag) { return new Element(tag); },\\n  addEventListener: function (type, fn) { (this.listeners[type] = this.listeners[type] || []).push(fn); },\\n  dispatch: function (type, event) { (this.listeners[type] || []).forEach(function (fn) { fn(event); }); }\\n};\\n\\nvar storeData = {};\\nvar localStorage = {\\n  getItem: function (k) { return Object.prototype.hasOwnProperty.call(storeData, k) ? storeData[k] : null; },\\n  setItem: function (k, v) { storeData[k] = String(v); },\\n  removeItem: function (k) { delete storeData[k]; }\\n};\\n\\nvar sandbox = {\\n  document: document,\\n  localStorage: localStorage,\\n  setTimeout: setTimeout,\\n  clearTimeout: clearTimeout,\\n  console: console,\\n  Math: Math,\\n  JSON: JSON,\\n  Map: Map,\\n  Set: Set,\\n  Object: Object,\\n  Array: Array,\\n  String: String,\\n  Number: Number,\\n  Date: Date,\\n  isNaN: isNaN,\\n  parseInt: parseInt\\n};\\nsandbox.self = sandbox;\\nsandbox.window = sandbox;\\nvm.createContext(sandbox);\\n\\nconsole.log('\\\\n2048 UI wiring\\\\n');\\n\\ncheck('index.html carries every id app.js looks up', function () {\\n  var app = fs.readFileSync(path.join(here, 'app.js'), 'utf8');\\n  var wanted = [];\\n  app.replace(/getElementById\\\\('([^']+)'\\\\)/g, function (_, id) { wanted.push(id); return _; });\\n  ok(wanted.length >= 10, 'found ' + wanted.length + ' lookups');\\n  wanted.forEach(function (id) { ok(ids[id], 'missing id in index.html: ' + id); });\\n});\\n\\ncheck('index.html loads both scripts, in order', function () {\\n  var scripts = [];\\n  html.replace(/<script src=\\"([^\\"]+)\\"><\\\\/script>/g, function (_, src) { scripts.push(src); return _; });\\n  eq(scripts.join(','), 'engine.js,app.js', 'script tags');\\n});\\n\\ncheck('the slide duration in app.js matches --slide in styles.css', function () {\\n  var app = fs.readFileSync(path.join(here, 'app.js'), 'utf8');\\n  var css = fs.readFileSync(path.join(here, 'styles.css'), 'utf8');\\n  var js = /SLIDE_MS\\\\s*=\\\\s*(\\\\d+)/.exec(app);\\n  var sheet = /--slide:\\\\s*(\\\\d+)ms/.exec(css);\\n  ok(js && sheet, 'both values found');\\n  eq(js[1], sheet[1], 'duration');\\n});\\n\\ncheck('engine.js and app.js load without throwing', function () {\\n  vm.runInContext(fs.readFileSync(path.join(here, 'engine.js'), 'utf8'), sandbox, { filename: 'engine.js' });\\n  ok(sandbox.Game2048, 'Game2048 exposed');\\n  vm.runInContext(fs.readFileSync(path.join(here, 'app.js'), 'utf8'), sandbox, { filename: 'app.js' });\\n});\\n\\ncheck('two tiles are on the board at boot, with score and best shown', function () {\\n  eq(ids.tiles.children.length, 2, 'tile elements');\\n  eq(ids.score.textContent, '0', 'score');\\n  eq(ids.best.textContent, '0', 'best');\\n  eq(ids.undo.disabled, true, 'undo disabled with no history');\\n  eq(ids.overlay.hidden, true, 'no overlay');\\n});\\n\\nfunction press(key) {\\n  var prevented = false;\\n  document.dispatch('keydown', {\\n    key: key,\\n    preventDefault: function () { prevented = true; }\\n  });\\n  return prevented;\\n}\\n\\ncheck('arrow keys move tiles and are swallowed (no page scroll)', function () {\\n  ok(press('ArrowLeft'), 'ArrowLeft prevented default');\\n  ok(press('ArrowUp'), 'ArrowUp prevented default');\\n  ok(press('ArrowRight'), 'ArrowRight prevented default');\\n  ok(press('ArrowDown'), 'ArrowDown prevented default');\\n  ok(ids.tiles.children.length >= 2, 'tiles still rendered');\\n  ok(ids.tiles.children.every(function (t) { return t.has('tile'); }), 'tile class');\\n});\\n\\ncheck('every rendered tile has a value and a grid position', function () {\\n  ids.tiles.children.forEach(function (t) {\\n    ok(t.dataset.value, 'data-value set');\\n    ok(t.styles['--r'] !== undefined && t.styles['--c'] !== undefined, '--r/--c set');\\n    ok(Number(t.styles['--r']) >= 0 && Number(t.styles['--r']) <= 3, 'row in range');\\n    ok(Number(t.styles['--c']) >= 0 && Number(t.styles['--c']) <= 3, 'col in range');\\n    ok(t.firstChild && t.firstChild.has('tile-inner'), 'inner node');\\n  });\\n});\\n\\ncheck('undo becomes available after a move, and rewinds the board', function () {\\n  // Force a guaranteed-legal sequence, then undo it.\\n  var moved = ['ArrowLeft', 'ArrowUp', 'ArrowRight', 'ArrowDown'].some(function (k) {\\n    var before = snapshotTiles();\\n    press(k);\\n    return snapshotTiles() !== before;\\n  });\\n  ok(moved || ids.undo.disabled === false, 'at least one move landed');\\n  eq(ids.undo.disabled, false, 'undo enabled');\\n  var before = snapshotTiles();\\n  ids.undo.dispatch('click', {});\\n  ok(snapshotTiles() !== before, 'board rewound');\\n});\\n\\nfunction snapshotTiles() {\\n  return ids.tiles.children.map(function (t) {\\n    return t.styles['--r'] + ':' + t.styles['--c'] + '=' + t.dataset.value;\\n  }).sort().join(',');\\n}\\n\\ncheck('new game resets the board to two tiles and a zero score', function () {\\n  ids.new.dispatch('click', {});\\n  eq(ids.tiles.children.length, 2, 'tile elements');\\n  eq(ids.score.textContent, '0', 'score');\\n  eq(ids.undo.disabled, true, 'history cleared');\\n});\\n\\ncheck('score, best and persistence update through the UI', function () {\\n  var before = Number(ids.score.textContent);\\n  for (var i = 0; i < 60; i++) press(['ArrowLeft', 'ArrowUp', 'ArrowRight', 'ArrowDown'][i % 4]);\\n  var after = Number(ids.score.textContent);\\n  ok(after > before, 'score climbed to ' + after);\\n  eq(ids.best.textContent, String(Math.max(after, Number(ids.best.textContent))), 'best tracks score');\\n  ok(storeData['game2048.best'], 'best written to storage');\\n  ok(storeData['game2048.state'], 'state written to storage');\\n});\\n\\ncheck('swipe gestures move tiles too', function () {\\n  ids.new.dispatch('click', {});\\n  var before = snapshotTiles();\\n  ids.board.dispatch('pointerdown', { button: 0, clientX: 200, clientY: 200 });\\n  ids.board.dispatch('pointerup', { button: 0, clientX: 60, clientY: 205 });\\n  ok(snapshotTiles() !== before, 'a left swipe changed the board');\\n\\n  // A tap that never travels far enough is not a swipe.\\n  var steady = snapshotTiles();\\n  ids.board.dispatch('pointerdown', { button: 0, clientX: 200, clientY: 200 });\\n  ids.board.dispatch('pointerup', { button: 0, clientX: 205, clientY: 203 });\\n  eq(snapshotTiles(), steady, 'tap ignored');\\n});\\n\\n/* Seed a board into storage and boot a fresh copy of the app onto it. */\\nfunction reboot(state) {\\n  storeData['game2048.state'] = JSON.stringify(state);\\n  resetIds();\\n  document.listeners = {};\\n  var fresh = Object.assign({}, sandbox);\\n  fresh.self = fresh;\\n  fresh.window = fresh;\\n  vm.createContext(fresh);\\n  vm.runInContext(fs.readFileSync(path.join(here, 'engine.js'), 'utf8'), fresh, { filename: 'engine.js' });\\n  vm.runInContext(fs.readFileSync(path.join(here, 'app.js'), 'utf8'), fresh, { filename: 'app.js' });\\n}\\n\\ncheck('the win overlay offers keep-going, and keep-going dismisses it', function () {\\n  reboot({\\n    cells: [{ id: 1, value: 1024 }, { id: 2, value: 1024 }].concat(new Array(14).fill(null)),\\n    score: 0, won: false, keepGoing: false, over: false, nextId: 3, history: []\\n  });\\n  press('ArrowLeft');\\n  eq(ids.overlay.hidden, false, 'overlay shown');\\n  eq(ids['overlay-message'].textContent, 'You win!', 'message');\\n  eq(ids['keep-going'].hidden, false, 'keep going offered');\\n  eq(ids.overlay.has('win'), true, 'win styling');\\n\\n  // While the overlay is up, moves are ignored.\\n  var frozen = snapshotTiles();\\n  press('ArrowRight');\\n  eq(snapshotTiles(), frozen, 'input paused on the win screen');\\n\\n  ids['keep-going'].dispatch('click', {});\\n  eq(ids.overlay.hidden, true, 'overlay dismissed');\\n  press('ArrowRight');\\n  ok(snapshotTiles() !== frozen, 'play continues after winning');\\n});\\n\\ncheck('the game-over overlay appears with retry only', function () {\\n  var locked = [];\\n  var board = [\\n    [2, 4, 8, 16],\\n    [4, 8, 16, 2],\\n    [8, 16, 2, 4],\\n    [16, 2, 4, 8]\\n  ];\\n  var id = 1;\\n  board.forEach(function (row) { row.forEach(function (v) { locked.push({ id: id++, value: v }); }); });\\n  reboot({\\n    cells: locked, score: 1234, won: false, keepGoing: false, over: true, nextId: id, history: []\\n  });\\n\\n  eq(ids.overlay.hidden, false, 'overlay shown at boot');\\n  eq(ids['overlay-message'].textContent, 'Game over!', 'message');\\n  eq(ids['keep-going'].hidden, true, 'no keep-going on a loss');\\n  eq(ids.score.textContent, '1234', 'final score shown');\\n\\n  ids.retry.dispatch('click', {});\\n  eq(ids.overlay.hidden, true, 'retry starts over');\\n  eq(ids.tiles.children.length, 2, 'fresh board');\\n});\\n\\nconsole.log('\\\\n' + passed + ' passed, ' + failed + ' failed\\\\n');\\nprocess.exit(failed ? 1 : 0);\\n"},{"path":"styles.css","bytes":7342,"text":":root {\\n  /* Kept in px so the same value works for grid gaps and for translate()\\n     offsets, where a percentage would resolve against the tile's own width. */\\n  --gap: clamp(7px, 2.9vw, 13px);\\n  --slide: 110ms;\\n  --pop: 150ms;\\n\\n  --bg: #faf8ef;\\n  --ink: #776e65;\\n  --ink-dim: #bbada0;\\n  --board: #bbada0;\\n  --cell: rgba(238, 228, 218, 0.35);\\n  --btn: #8f7a66;\\n  --btn-hover: #9f8b77;\\n  --light: #f9f6f2;\\n}\\n\\n* { box-sizing: border-box; }\\n\\nhtml, body {\\n  margin: 0;\\n  padding: 0;\\n  background: var(--bg);\\n  color: var(--ink);\\n  font-family: \\"Clear Sans\\", \\"Helvetica Neue\\", Helvetica, Arial, sans-serif;\\n  -webkit-font-smoothing: antialiased;\\n}\\n\\nbody {\\n  display: flex;\\n  justify-content: center;\\n  padding: 24px 16px 48px;\\n  min-height: 100vh;\\n  overscroll-behavior: none;\\n}\\n\\n.app {\\n  width: 100%;\\n  max-width: 480px;\\n}\\n\\n/* ------------------------------------------------------------------ head */\\n\\nheader {\\n  display: flex;\\n  align-items: flex-start;\\n  justify-content: space-between;\\n  gap: 12px;\\n  margin-bottom: 12px;\\n}\\n\\nh1 {\\n  font-size: clamp(44px, 13vw, 66px);\\n  line-height: 1;\\n  margin: 0;\\n  font-weight: 800;\\n  color: #6d6459;\\n}\\n\\n.scores { display: flex; gap: 8px; }\\n\\n.score {\\n  background: var(--board);\\n  border-radius: 6px;\\n  padding: 6px 14px;\\n  min-width: 76px;\\n  text-align: center;\\n  color: #eee4da;\\n  position: relative;\\n}\\n\\n.score .label {\\n  display: block;\\n  font-size: 11px;\\n  letter-spacing: 0.09em;\\n  text-transform: uppercase;\\n  font-weight: 700;\\n  color: #eee4da;\\n  opacity: 0.8;\\n}\\n\\n.score .value {\\n  display: block;\\n  font-size: 23px;\\n  font-weight: 800;\\n  color: #fff;\\n  line-height: 1.25;\\n}\\n\\n/* +N floater on the score when a merge lands */\\n.gain {\\n  position: absolute;\\n  left: 0;\\n  right: 0;\\n  top: 12px;\\n  font-size: 20px;\\n  font-weight: 800;\\n  color: rgba(119, 110, 101, 0.9);\\n  pointer-events: none;\\n  animation: gain 620ms ease-in both;\\n}\\n\\n@keyframes gain {\\n  0%   { opacity: 0.9; transform: translateY(0); }\\n  100% { opacity: 0; transform: translateY(-34px); }\\n}\\n\\n.toolbar {\\n  display: flex;\\n  align-items: center;\\n  justify-content: space-between;\\n  gap: 12px;\\n  margin-bottom: 12px;\\n}\\n\\n.hint {\\n  font-size: 13px;\\n  line-height: 1.35;\\n  color: #8a8078;\\n  margin: 0;\\n}\\n\\n.actions { display: flex; gap: 8px; flex: none; }\\n\\nbutton {\\n  font-family: inherit;\\n  font-size: 14px;\\n  font-weight: 700;\\n  color: var(--light);\\n  background: var(--btn);\\n  border: 0;\\n  border-radius: 6px;\\n  padding: 10px 14px;\\n  cursor: pointer;\\n  transition: background 120ms ease;\\n}\\n\\nbutton:hover { background: var(--btn-hover); }\\nbutton:focus-visible { outline: 3px solid #a8998a; outline-offset: 2px; }\\nbutton:disabled { opacity: 0.45; cursor: default; background: var(--btn); }\\n\\n/* ----------------------------------------------------------------- board */\\n\\n.board {\\n  position: relative;\\n  width: 100%;\\n  aspect-ratio: 1 / 1;\\n  background: var(--board);\\n  border-radius: 8px;\\n  padding: var(--gap);\\n  touch-action: none;\\n  user-select: none;\\n  -webkit-user-select: none;\\n}\\n\\n.grid {\\n  position: absolute;\\n  inset: var(--gap);\\n  display: grid;\\n  grid-template-columns: repeat(4, 1fr);\\n  grid-template-rows: repeat(4, 1fr);\\n  gap: var(--gap);\\n}\\n\\n.grid .cell { background: var(--cell); border-radius: 5px; }\\n\\n.tiles {\\n  position: absolute;\\n  inset: var(--gap);\\n  pointer-events: none;\\n}\\n\\n/*\\n * A tile is positioned by translating it by whole cell-widths (+ gap).\\n * \`100%\` inside translate() resolves against the tile's own size, so this\\n * stays correct at any board size.\\n */\\n.tile {\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: calc((100% - 3 * var(--gap)) / 4);\\n  height: calc((100% - 3 * var(--gap)) / 4);\\n  transform: translate(\\n    calc(var(--c) * (100% + var(--gap))),\\n    calc(var(--r) * (100% + var(--gap)))\\n  );\\n  transition: transform var(--slide) ease-in-out;\\n  will-change: transform;\\n}\\n\\n.tile-inner {\\n  width: 100%;\\n  height: 100%;\\n  border-radius: 5px;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  font-weight: 800;\\n  font-size: clamp(20px, 7.5vw, 36px);\\n  background: #eee4da;\\n  color: var(--ink);\\n}\\n\\n.tile[data-value=\\"2\\"]    .tile-inner { background: #eee4da; }\\n.tile[data-value=\\"4\\"]    .tile-inner { background: #ede0c8; }\\n.tile[data-value=\\"8\\"]    .tile-inner { background: #f2b179; color: var(--light); }\\n.tile[data-value=\\"16\\"]   .tile-inner { background: #f59563; color: var(--light); }\\n.tile[data-value=\\"32\\"]   .tile-inner { background: #f67c5f; color: var(--light); }\\n.tile[data-value=\\"64\\"]   .tile-inner { background: #f65e3b; color: var(--light); }\\n.tile[data-value=\\"128\\"]  .tile-inner { background: #edcf72; color: var(--light); font-size: clamp(17px, 6.2vw, 30px); box-shadow: 0 0 22px 8px rgba(243, 215, 116, 0.24); }\\n.tile[data-value=\\"256\\"]  .tile-inner { background: #edcc61; color: var(--light); font-size: clamp(17px, 6.2vw, 30px); box-shadow: 0 0 22px 10px rgba(243, 215, 116, 0.31); }\\n.tile[data-value=\\"512\\"]  .tile-inner { background: #edc850; color: var(--light); font-size: clamp(17px, 6.2vw, 30px); box-shadow: 0 0 22px 12px rgba(243, 215, 116, 0.39); }\\n.tile[data-value=\\"1024\\"] .tile-inner { background: #edc53f; color: var(--light); font-size: clamp(13px, 4.9vw, 24px); box-shadow: 0 0 24px 14px rgba(243, 215, 116, 0.45); }\\n.tile[data-value=\\"2048\\"] .tile-inner { background: #edc22e; color: var(--light); font-size: clamp(13px, 4.9vw, 24px); box-shadow: 0 0 26px 16px rgba(243, 215, 116, 0.55); }\\n.tile[data-value=\\"super\\"] .tile-inner { background: #3c3a32; color: var(--light); font-size: clamp(12px, 4.4vw, 21px); }\\n\\n/* Spawned tiles pop in once the sliding tiles have settled. */\\n.tile-new .tile-inner {\\n  animation: appear var(--pop) ease both;\\n  animation-delay: var(--slide);\\n}\\n\\n@keyframes appear {\\n  from { opacity: 0; transform: scale(0); }\\n  to   { opacity: 1; transform: scale(1); }\\n}\\n\\n.tile-merged .tile-inner { animation: bump 180ms ease; }\\n\\n@keyframes bump {\\n  0%   { transform: scale(1); }\\n  45%  { transform: scale(1.18); }\\n  100% { transform: scale(1); }\\n}\\n\\n/* The absorbed half of a merge slides under the survivor, then is removed. */\\n.tile-absorbed { z-index: 0; }\\n.tile-merged { z-index: 2; }\\n\\n/* --------------------------------------------------------------- overlay */\\n\\n.overlay {\\n  position: absolute;\\n  inset: 0;\\n  border-radius: 8px;\\n  display: flex;\\n  flex-direction: column;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 18px;\\n  text-align: center;\\n  background: rgba(238, 228, 218, 0.73);\\n  animation: fade 320ms ease both;\\n  animation-delay: 120ms;\\n  z-index: 10;\\n}\\n\\n.overlay[hidden] { display: none; }\\n\\n.overlay.win { background: rgba(237, 194, 46, 0.5); }\\n\\n.overlay p {\\n  margin: 0;\\n  font-size: clamp(30px, 9vw, 46px);\\n  font-weight: 800;\\n  color: var(--ink);\\n}\\n\\n.overlay.win p { color: #f9f6f2; text-shadow: 0 2px 0 rgba(119, 110, 101, 0.35); }\\n\\n.overlay .buttons { display: flex; gap: 10px; }\\n\\n@keyframes fade { from { opacity: 0; } to { opacity: 1; } }\\n\\nfooter {\\n  margin-top: 16px;\\n  font-size: 12.5px;\\n  line-height: 1.5;\\n  color: #9c9086;\\n}\\n\\nfooter kbd {\\n  font-family: inherit;\\n  font-size: 11px;\\n  font-weight: 700;\\n  background: #eee4da;\\n  border-radius: 3px;\\n  padding: 1px 5px;\\n  color: #7b7269;\\n}\\n\\n@media (prefers-reduced-motion: reduce) {\\n  .tile { transition-duration: 1ms; }\\n  .tile-new .tile-inner,\\n  .tile-merged .tile-inner,\\n  .overlay,\\n  .gain { animation-duration: 1ms; animation-delay: 0ms; }\\n}\\n"},{"path":"test.js","bytes":12655,"text":"/*\\n * Engine tests. No dependencies:  node test.js\\n * One check per capability under \\"AI\\" in the spec.\\n */\\n'use strict';\\n\\nvar Game2048 = require('./engine.js').Game2048;\\n\\nvar passed = 0;\\nvar failed = 0;\\n\\nfunction check(name, fn) {\\n  try {\\n    fn();\\n    passed++;\\n    console.log('  ok   ' + name);\\n  } catch (e) {\\n    failed++;\\n    console.log('  FAIL ' + name + '\\\\n       ' + e.message);\\n  }\\n}\\n\\nfunction eq(actual, expected, what) {\\n  var a = JSON.stringify(actual);\\n  var b = JSON.stringify(expected);\\n  if (a !== b) throw new Error((what || 'value') + ': expected ' + b + ', got ' + a);\\n}\\n\\nfunction ok(cond, what) {\\n  if (!cond) throw new Error(what || 'expected truthy');\\n}\\n\\n/* A storage stand-in, so persistence is testable off-browser. */\\nfunction memoryStorage() {\\n  var data = {};\\n  return {\\n    getItem: function (k) { return Object.prototype.hasOwnProperty.call(data, k) ? data[k] : null; },\\n    setItem: function (k, v) { data[k] = String(v); },\\n    removeItem: function (k) { delete data[k]; },\\n    _data: data\\n  };\\n}\\n\\n/* Deterministic rng: replays a fixed sequence, then falls back to 0. */\\nfunction scripted(values) {\\n  var i = 0;\\n  return function () { return i < values.length ? values[i++] : 0; };\\n}\\n\\nfunction fresh(rows) {\\n  var g = new Game2048({ storage: null, rng: scripted([]) });\\n  if (rows) g.setGrid(rows);\\n  return g;\\n}\\n\\nvar _ = 0;\\n\\nconsole.log('\\\\n2048 engine\\\\n');\\n\\ncheck('4x4 grid state - 16 cells', function () {\\n  var g = fresh();\\n  eq(g.cells.length, 16, 'cell count');\\n  eq(g.getGrid().length, 4, 'rows');\\n  eq(g.getGrid()[0].length, 4, 'cols');\\n});\\n\\ncheck('two starting tiles, before the first move', function () {\\n  for (var i = 0; i < 50; i++) {\\n    var g = new Game2048({ storage: null });\\n    eq(g.tiles().length, 2, 'starting tiles');\\n    g.tiles().forEach(function (t) { ok(t.value === 2 || t.value === 4, 'start value ' + t.value); });\\n  }\\n});\\n\\ncheck('spawn is 90% a 2 and 10% a 4', function () {\\n  // rng() picks the cell first, then the value: <0.9 -> 2, else 4.\\n  var g = fresh([[_, _, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g.rng = scripted([0, 0.5]);\\n  eq(g.spawn().value, 2, 'value at 0.5');\\n  g.setGrid([[_, _, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g.rng = scripted([0, 0.95]);\\n  eq(g.spawn().value, 4, 'value at 0.95');\\n\\n  // Distribution sanity over many draws with a real random source.\\n  var twos = 0, total = 4000;\\n  for (var i = 0; i < total; i++) {\\n    var h = fresh([[_, _, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n    h.rng = Math.random;\\n    if (h.spawn().value === 2) twos++;\\n  }\\n  var ratio = twos / total;\\n  ok(ratio > 0.86 && ratio < 0.94, 'ratio of 2s was ' + ratio.toFixed(3));\\n});\\n\\ncheck('spawn lands in an empty cell', function () {\\n  var g = fresh([\\n    [2, 4, 8, 16],\\n    [2, 4, 8, 16],\\n    [2, 4, 8, 16],\\n    [2, 4, 8, _]\\n  ]);\\n  var t = g.spawn();\\n  eq([t.r, t.c], [3, 3], 'only empty cell');\\n  eq(g.spawn(), null, 'no room left');\\n});\\n\\ncheck('a tile spawns after every move that changes the board', function () {\\n  var g = fresh([\\n    [2, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.rng = scripted([0.99, 0.5]);\\n  var res = g.move('right');\\n  ok(res, 'move happened');\\n  eq(g.tiles().length, 2, 'tile count after move');\\n  ok(res.tiles.some(function (r) { return r.spawned; }), 'spawn recorded');\\n});\\n\\ncheck('slide left', function () {\\n  var g = fresh([\\n    [_, _, 2, _],\\n    [_, 4, _, 8],\\n    [_, _, _, _],\\n    [16, _, _, _]\\n  ]);\\n  g.move('left');\\n  var rows = g.getGrid();\\n  eq(rows[0].slice(0, 1), [2], 'row 0');\\n  eq(rows[1].slice(0, 2), [4, 8], 'row 1');\\n  eq(rows[3].slice(0, 1), [16], 'row 3');\\n});\\n\\ncheck('slide right / up / down travel as far as they can', function () {\\n  var g = fresh([[_, 2, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g.move('right');\\n  eq(g.getGrid()[0][3], 2, 'right edge');\\n\\n  g = fresh([[_, _, _, _], [_, _, _, _], [_, _, _, _], [_, _, 4, _]]);\\n  g.move('up');\\n  eq(g.getGrid()[0][2], 4, 'top edge');\\n\\n  g = fresh([[8, _, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g.move('down');\\n  eq(g.getGrid()[3][0], 8, 'bottom edge');\\n});\\n\\ncheck('merge equal adjacent tiles, doubling', function () {\\n  var g = fresh([\\n    [2, 2, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.move('left');\\n  eq(g.getGrid()[0][0], 4, 'merged value');\\n});\\n\\ncheck('merge across a gap', function () {\\n  var g = fresh([\\n    [2, _, _, 2],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.move('left');\\n  eq(g.getGrid()[0][0], 4, 'merged over the gap');\\n});\\n\\ncheck('one merge per tile per move: 4,4,8 left gives 8,8', function () {\\n  var g = fresh([\\n    [4, 4, 8, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.move('left');\\n  eq(g.getGrid()[0].slice(0, 2), [8, 8], 'row 0');\\n});\\n\\ncheck('one merge per tile per move: 2,2,2,2 left gives 4,4', function () {\\n  var g = fresh([\\n    [2, 2, 2, 2],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.move('left');\\n  eq(g.getGrid()[0].slice(0, 2), [4, 4], 'row 0');\\n});\\n\\ncheck('merge direction: 2,2,2 left gives 4,2 (not 2,4)', function () {\\n  var g = fresh([\\n    [2, 2, 2, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.move('left');\\n  eq(g.getGrid()[0].slice(0, 2), [4, 2], 'nearest pair merges');\\n\\n  var h = fresh([\\n    [2, 2, 2, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  h.move('right');\\n  eq(h.getGrid()[0].slice(2), [2, 4], 'nearest pair merges going right');\\n});\\n\\ncheck('a move that changes nothing is rejected, and does not spawn', function () {\\n  var g = fresh([\\n    [2, 4, 8, 16],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  var before = g.tiles().length;\\n  eq(g.move('up'), null, 'already at the top');\\n  eq(g.tiles().length, before, 'no tile spawned');\\n  eq(g.canUndo(), false, 'nothing pushed to history');\\n});\\n\\ncheck('score increases by each merged value', function () {\\n  var g = fresh([\\n    [2, 2, 4, 4],\\n    [8, 8, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  var res = g.move('left');\\n  eq(res.gained, 4 + 8 + 16, 'gained');\\n  eq(g.score, 28, 'score');\\n\\n  var h = fresh([[2, _, _, 4], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  h.move('left');\\n  eq(h.score, 0, 'sliding without merging scores nothing');\\n});\\n\\ncheck('best score persists across a reload', function () {\\n  var store = memoryStorage();\\n  var g = new Game2048({ storage: store });\\n  g.setGrid([[2, 2, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g.move('left');\\n  eq(g.best, 4, 'best updated');\\n\\n  var reloaded = new Game2048({ storage: store });\\n  eq(reloaded.best, 4, 'best after reload');\\n\\n  // Best is a high-water mark: a fresh game does not clear it.\\n  reloaded.newGame();\\n  eq(reloaded.best, 4, 'best survives a new game');\\n  eq(new Game2048({ storage: store }).best, 4, 'and another reload');\\n});\\n\\ncheck('game state persists across a reload', function () {\\n  var store = memoryStorage();\\n  var g = new Game2048({ storage: store });\\n  g.setGrid([[2, 2, _, _], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g.move('left');\\n  var grid = g.getGrid();\\n  var score = g.score;\\n\\n  var reloaded = new Game2048({ storage: store });\\n  eq(reloaded.getGrid(), grid, 'grid');\\n  eq(reloaded.score, score, 'score');\\n});\\n\\ncheck('win at 2048', function () {\\n  var g = fresh([\\n    [1024, 1024, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  eq(g.won, false, 'not won yet');\\n  var res = g.move('left');\\n  eq(res.justWon, true, 'justWon');\\n  eq(g.won, true, 'won');\\n  eq(g.getGrid()[0][0], 2048, 'the winning tile');\\n});\\n\\ncheck('the game continues after winning', function () {\\n  var g = fresh([\\n    [1024, 1024, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  g.move('left');\\n  g.keepGoing = true;\\n  var res = g.move('right');\\n  ok(res, 'still playable after the win');\\n  eq(g.over, false, 'not over');\\n\\n  // And winning is only announced once.\\n  var g2 = fresh([[2048, _, _, 2], [_, _, _, _], [_, _, _, _], [_, _, _, _]]);\\n  g2.won = true;\\n  var r2 = g2.move('left');\\n  eq(r2.justWon, false, 'no second win announcement');\\n});\\n\\ncheck('game over when the grid is full with no equal neighbours', function () {\\n  var g = fresh([\\n    [2, 4, 2, 4],\\n    [4, 2, 4, 2],\\n    [2, 4, 2, 4],\\n    [4, 2, 4, 2]\\n  ]);\\n  eq(g.canMove(), false, 'no move possible');\\n  eq(g.over, true, 'over');\\n  ['up', 'down', 'left', 'right'].forEach(function (d) {\\n    eq(g.move(d), null, 'move ' + d + ' rejected');\\n  });\\n});\\n\\ncheck('a full grid with a mergeable pair is not game over', function () {\\n  var g = fresh([\\n    [2, 4, 2, 4],\\n    [4, 2, 4, 2],\\n    [2, 4, 2, 4],\\n    [4, 2, 4, 4]\\n  ]);\\n  eq(g.canMove(), true, 'a merge is available');\\n  eq(g.over, false, 'not over');\\n});\\n\\ncheck('game over is detected after the final spawn fills the grid', function () {\\n  // Only the last row can move; afterwards the single hole is at (3,3) and\\n  // whatever spawns there, a 2, leaves no equal neighbours anywhere.\\n  var h = fresh([\\n    [2, 4, 8, 16],\\n    [4, 8, 16, 2],\\n    [8, 16, 2, 4],\\n    [_, 16, 2, 4]\\n  ]);\\n  h.rng = scripted([0, 0.5]); // the only empty cell, value 2\\n  var res = h.move('left');\\n  eq(res.over, true, 'the spawn locks the board');\\n  eq(h.over, true, 'over flag');\\n});\\n\\ncheck('undo restores the previous board and score', function () {\\n  var g = fresh([\\n    [2, 2, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  var before = g.getGrid();\\n  g.move('left');\\n  ok(g.score === 4, 'score moved');\\n  eq(g.canUndo(), true, 'undo available');\\n  eq(g.undo(), true, 'undo ran');\\n  eq(g.getGrid(), before, 'board restored');\\n  eq(g.score, 0, 'score restored');\\n  eq(g.canUndo(), false, 'history consumed');\\n  eq(g.undo(), false, 'nothing more to undo');\\n});\\n\\ncheck('undo works more than one level deep', function () {\\n  var g = new Game2048({ storage: null });\\n  var snapshots = [g.getGrid()];\\n  for (var i = 0; i < 6; i++) {\\n    var dirs = ['left', 'up', 'right', 'down'];\\n    for (var d = 0; d < dirs.length; d++) {\\n      if (g.move(dirs[d])) { snapshots.push(g.getGrid()); break; }\\n    }\\n  }\\n  var levels = snapshots.length - 1;\\n  ok(levels >= 3, 'made ' + levels + ' moves');\\n  for (var k = levels; k >= 1; k--) {\\n    eq(g.getGrid(), snapshots[k], 'state at depth ' + k);\\n    eq(g.undo(), true, 'undo at depth ' + k);\\n  }\\n  eq(g.getGrid(), snapshots[0], 'back to the start');\\n});\\n\\ncheck('undo clears game over', function () {\\n  var g = fresh([\\n    [2, 4, 8, 16],\\n    [4, 8, 16, 2],\\n    [8, 16, 2, 4],\\n    [_, 16, 2, 4]\\n  ]);\\n  g.rng = scripted([0, 0.5]);\\n  g.move('left');\\n  eq(g.over, true, 'locked');\\n  g.undo();\\n  eq(g.over, false, 'playable again');\\n  ok(g.move('left'), 'and moves work');\\n});\\n\\ncheck('tile identity survives a move, so the UI can animate it', function () {\\n  var g = fresh([\\n    [2, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  var id = g.at(0, 0).id;\\n  var res = g.move('right');\\n  var record = res.tiles.filter(function (t) { return !t.spawned; })[0];\\n  eq(record.sources.length, 1, 'one source');\\n  eq(record.sources[0].id, id, 'same tile');\\n  eq([record.r, record.c], [0, 3], 'new position');\\n  eq(g.at(0, 3).id, id, 'id kept on the board');\\n});\\n\\ncheck('a merge reports both source tiles and their old positions', function () {\\n  var g = fresh([\\n    [2, _, _, 2],\\n    [_, _, _, _],\\n    [_, _, _, _],\\n    [_, _, _, _]\\n  ]);\\n  var res = g.move('left');\\n  var merge = res.tiles.filter(function (t) { return t.merged; })[0];\\n  ok(merge, 'a merge was reported');\\n  eq(merge.value, 4, 'merged value');\\n  eq(merge.sources.length, 2, 'two sources');\\n  eq(merge.sources.map(function (s) { return s.c; }), [0, 3], 'source columns');\\n});\\n\\ncheck('a long random game never breaks an invariant', function () {\\n  for (var run = 0; run < 200; run++) {\\n    var g = new Game2048({ storage: null });\\n    var dirs = ['up', 'down', 'left', 'right'];\\n    for (var step = 0; step < 400 && !g.over; step++) {\\n      var res = g.move(dirs[Math.floor(Math.random() * 4)]);\\n      if (!res) continue;\\n      var tiles = g.tiles();\\n      ok(tiles.length <= 16, 'at most 16 tiles');\\n      var ids = {};\\n      tiles.forEach(function (t) {\\n        ok(!ids[t.id], 'unique tile ids');\\n        ids[t.id] = true;\\n        ok(t.value >= 2 && (t.value & (t.value - 1)) === 0, 'power of two: ' + t.value);\\n        var cell = g.at(t.r, t.c);\\n        ok(cell === t, 'tile knows its own cell');\\n      });\\n      ok(g.score >= 0, 'score is non-negative');\\n      ok(g.best >= g.score, 'best tracks score');\\n    }\\n    ok(g.over ? !g.canMove() : g.canMove(), 'over flag agrees with canMove');\\n  }\\n});\\n\\nconsole.log('\\\\n' + passed + ' passed, ' + failed + ' failed\\\\n');\\nprocess.exit(failed ? 1 : 0);\\n"}]`),r={slug:e,selfReport:n,files:t};export{r as default,t as files,n as selfReport,e as slug};
